class ProjectManager {
}

class Project {
  +StartDate
  +EndDate
}

class Team {
}

class WorkProduct {
  +Description
  +PercentComplete
}

class Requirement extends WorkProduct {
  +Validate()
  +Publish()
}

class System extends WorkProduct {
  +Validate()
}

ProjectManager "1" -- "*" Project : manages
ProjectManager "1" -- "*" Team : leads
Team "1..*" -- "1" Project : execute
Project "1" -- "*" Requirement : Input
Project "1" -- "*" System : Output

@enduml

